/**
 * Cyrus R5 delivery job (worker side): Nxeon's implementation of the orchestrator's host seam
 * (lib/cyrus/delivery/types.ts DeliveryHost) and the job entry point.
 *
 * Wiring (the only one, and only as far as is clearly safe): a GAME_MOD_SYNC job whose payload carries
 * `{ cyrusDelivery: { v: 1, op: "deliver" | "uninstall", buildId?, projectId?, serverModId?, restartPolicy? } }`
 * (a payload DISCRIMINATOR on an existing job type: no new enum value, no new table) is handed to
 * `cyrusDeliveryJob` instead of the normal mod reconcile. Nothing enqueues such a job yet (no route, no UI), and the
 * handler refuses unless CYRUS_DELIVERY=1. Each part is still behind its own flag (CYRUS_MANAGED_PLUGINS_REAL,
 * CYRUS_DATAPACK_DELIVERY_REAL (+ CYRUS_WORLDGEN), CYRUS_CREATURES) and the Mods engine's ENABLE_REAL_GAMEMODS.
 * The GAME_MOD_SYNC job already holds the per-server lock (one job per server at a time).
 *
 * The result (steps, rollback, health, notes) is stored on the job's payload.result.cyrusDelivery: the admin read
 * model (lib/cyrus/delivery/admin.ts) lists recent deliveries from there.
 *
 * SANDBOX: the server is the fake guest dir; a "restart" cannot boot anything there, so the health probe reports
 * `real: false` and a delivery that needs a restart is honestly rolled back (use restartPolicy "next_restart" there).
 */
import type { Job, Prisma } from "@prisma/client";
import { readFile } from "node:fs/promises";
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { LocalGuestFs, sandboxGuestRoot, type GuestFs } from "../lib/mods/guest-fs";
import { SshGuestFs } from "./mods-guest-ssh";
import { catalogFacts, serverFacts } from "../lib/mods/facts";
import { engineInstallerFor } from "../lib/mods/installers";
import { installOrUpdate, uninstall as engineUninstall } from "../lib/mods/engine";
import { safeFetch } from "../lib/mods/safe-fetch";
import { dbMirrorLookup } from "../lib/mods/mirror";
import { withServerSsh, exec as sshExec } from "../lib/ssh-exec";
import { controlSpec, runRcon } from "../lib/game-control";
import { noRetry, powerScript } from "./game-control";
import { ensureCyrusGameMod } from "../lib/cyrus-mods/registry";
