// and the token economy (cyrus_tok_live). Studio open to the public while tokens are off means builds that nobody
// meters or pays for, and (before this guard) a free choice of any model. This pure module is the one place that
// decides what the pair means; everything that opens Cyrus to non-preview accounts must go through it.
// Pure (unit-tested without any framework imports).

export type LaunchState =
  /** Studio flag off: only the private preview can build. (Tokens may or may not be live; that is fine.) */
  | "closed"
  /** Both on: the public may build, metered by tokens. */
  | "public"
  /** Studio flag on but tokens off: INVALID. Non-preview accounts are refused (fail closed). */
  | "unmetered";

export function launchState(o: { studioPublic: boolean; tokensLive: boolean }): LaunchState {
  if (!o.studioPublic) return "closed";
  return o.tokensLive ? "public" : "unmetered";
}

/** True only when the public may open the studio and build. */
export const publicMayBuild = (o: { studioPublic: boolean; tokensLive: boolean }): boolean => launchState(o) === "public";

/** The message an operator sees when the flags are in the invalid combination. */
export const UNMETERED_NOTICE =
  "Cyrus studio is set public but the token economy is off: the public is blocked until cyrus_tok_live is on too (they must be turned on together).";
  try {
    return await getSettingBool(CYRUS_STUDIO_PUBLIC_FLAG, false);
  } catch {
    return false;
  }
}

/**
 * The public may build only when the studio flag AND the token economy are both on (lib/cyrus/launch-state.ts).
 * Fails CLOSED on any settings/DB error.
 */
export async function studioPublicEffective(): Promise<boolean> {
  try {
    const [studioPublic, tokensLive] = await Promise.all([getSettingBool(CYRUS_STUDIO_PUBLIC_FLAG, false), getSettingBool("cyrus_tok_live", false)]);
    return publicMayBuild({ studioPublic, tokensLive });
  } catch {
    return false;
  }
}

