/** USD per million tokens. All optional fields fall back to the input price. */
export type MeshgenPrices = { inputPerMTok: number; outputPerMTok: number; cacheReadPerMTok?: number; imagePerMTok?: number };

export const PRICE_SETTING_KEYS = {
  input: "cyrus_meshgen_price_input_per_mtok",
  output: "cyrus_meshgen_price_output_per_mtok",
  cacheRead: "cyrus_meshgen_price_cache_read_per_mtok",
} as const;

/** Prices from host settings. Missing or unparsable input/output -> null (tokens-only estimate). */
export function parsePrices(settings: Readonly<Record<string, string | undefined>>): MeshgenPrices | null {
  const num = (k: string) => { const v = settings[k]; if (v === undefined || v.trim() === "") return null; const n = Number(v); return Number.isFinite(n) && n >= 0 ? n : null; };
  const i = num(PRICE_SETTING_KEYS.input), o = num(PRICE_SETTING_KEYS.output), c = num(PRICE_SETTING_KEYS.cacheRead);
  if (i === null || o === null) return null;
  return c === null ? { inputPerMTok: i, outputPerMTok: o } : { inputPerMTok: i, outputPerMTok: o, cacheReadPerMTok: c };
}

export type TokenTotals = { inputTokens: number; cachedInputTokens: number; outputTokens: number };
export const totalTokens = (t: TokenTotals) => t.inputTokens + t.cachedInputTokens + t.outputTokens;

export function dollarsFor(t: TokenTotals, p: MeshgenPrices | null): number | null {
  if (!p) return null;
  const d = (t.inputTokens * p.inputPerMTok + t.cachedInputTokens * (p.cacheReadPerMTok ?? p.inputPerMTok) + t.outputTokens * p.outputPerMTok) / 1e6;
  return Math.round(d * 1e6) / 1e6;
}

export type CostEstimate = {
  rung: Rung;
  rounds: number;
  maxRounds: number;
  expected: TokenTotals & { totalTokens: number };
  worstCase: TokenTotals & { totalTokens: number };
  dollars: number | null;
  worstCaseDollars: number | null;
  basis: "measured" | "assumed";
  measuredTotal: readonly [number, number] | null;
  notes: string[];
};

function sum(p: RoundProfile, rounds: number, renders: boolean): TokenTotals {
  // Round 1 has no previous image to look at only when renders are off; with renders every round ends with one look.
  const img = renders ? p.imageInput : 0;
  return { inputTokens: (p.input + img) * rounds, cachedInputTokens: p.cachedInput * rounds, outputTokens: p.output * rounds };
}

