export type RenderHostSelection = { ok: true; host: RenderHost } | { ok: false; reason: string };

/** Off by default. CYRUS_SOUND_RENDER=relay (web process: via the worker) or ssh (worker / scripts only) (+ optional CYRUS_SOUND_RENDER_HOST / _ROOT / CYRUS_SOUND_LIBRARY_DIR / CYRUS_SOUND_FFMPEG_DIR). */
export function selectRenderHost(env: Record<string, string | undefined> = process.env): RenderHostSelection {
  const mode = (env.CYRUS_SOUND_RENDER ?? "").trim();
  if (!mode || mode === "off") return { ok: false, reason: "sound rendering is not switched on here (CYRUS_SOUND_RENDER)" };
  // Cyrus R5: the web process reaches the render host only through the worker's relay (./relay.ts)
  if (mode === "relay") {
    try { return { ok: true, host: relayRenderHost(env.CYRUS_SOUND_RELAY_URL ?? "", env.CYRUS_SOUND_RELAY_TOKEN ?? "") }; }
    catch (e) { return { ok: false, reason: `sound relay: ${(e as Error).message}` }; }
  }
  if (mode !== "ssh") return { ok: false, reason: `unknown CYRUS_SOUND_RENDER=${mode}` };
  // ssh to node-2 is the worker's job: the Next.js server never opens it (NEXT_RUNTIME is set only inside Next.js)
  if (env.NEXT_RUNTIME) return { ok: false, reason: "the web process never connects to the render host; set CYRUS_SOUND_RENDER=relay here and run the relay in the worker (CYRUS_SOUND_RELAY_PORT)" };
  try {
    return { ok: true, host: sshRenderHost({ host: env.CYRUS_SOUND_RENDER_HOST || NODE2, root: env.CYRUS_SOUND_RENDER_ROOT || undefined, libraryDir: env.CYRUS_SOUND_LIBRARY_DIR || undefined, ffmpegDir: env.CYRUS_SOUND_FFMPEG_DIR || undefine
  } catch (e) { return { ok: false, reason: (e as Error).message }; }
}

