/** Compact, JSON-safe result for the job row (no buffers). */
export function compactResult(r: DeliveryResult): Prisma.InputJsonValue {
  return JSON.parse(JSON.stringify({ ...r, health: r.health ? { ok: r.health.ok, problems: r.health.problems, report: r.health.report ? { ...r.health.report, errorLines: r.health.report.errorLines.slice(0, 10) } : null }
}

export async function cyrusDeliveryJob(job: Job): Promise<void> {
  const p = readDeliveryPayload(job.payload);
  if (!p || !job.serverId) throw new Error("cyrus delivery: bad payload");
  if (process.env[DELIVERY_FLAG] !== "1") { await noRetry(job.id); throw new Error(`Cyrus delivery is switched off (${DELIVERY_FLAG} is not 1); nothing was changed`); }
  const server = await loadServer(job.serverId);
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  let result: DeliveryResult;
  if (p.op === "uninstall") {
    const proj = await db.cyrusProject.findUnique({ where: { id: p.projectId! } });
    result = await uninstallMod(server.id, p.projectId!, nxeonDeliveryHost(server, { rootBuildId: proj?.rootBuildId ?? null }), { restartPolicy: p.restartPolicy });
  } else {
    const b = await db.modBuild.findUnique({ where: { id: p.buildId! } });
    if (!b || b.status !== "succeeded" || !b.jarPath) throw new Error("cyrus delivery: the build has no finished plugin");
    if (b.userId !== server.userId) { await noRetry(job.id); throw new Error("cyrus delivery: the build belongs to another account"); }
    const root = b.rootBuildId ?? b.id;
    const proj = await projectForRootBuild(root);
    const jar = await readFile(b.jarPath).catch(() => null);
    const revId = (b.result as { assets?: { revisionId?: string | null } } | null)?.assets?.revisionId ?? null;
    const dpRows = revId ? await db.cyrusProjectAsset.findMany({ where: { revisionId: revId, kind: "datapack" }, select: { assetKey: true, provenance: true } }) : [];
    const rel = releaseFromBuild(b, jar, { project: proj ? { id: proj.id, namespace: proj.namespace } : null, datapackAssets: dpRows });
    if (!rel.ok) { await noRetry(job.id); throw new Error(`cyrus delivery: ${rel.error}`); }
    result = await deliverMod(server.id, rel.release, nxeonDeliveryHost(server, { rootBuildId: root, buildId: b.id }), { restartPolicy: p.restartPolicy });
    result.notes.unshift(...rel.notes);
    if (result.ok && p.serverModId) {
      await db.serverMod.update({ where: { id: p.serverModId }, data: { status: "INSTALLED", versionId: b.id, fileName: b.jarName, error: null, targetVersionId: null } }).catch(() => {});

