/** Drafts that never take a request down: a missing table (schema not pushed yet) answers 503, not 500. */
function safeDrafts(inner: DraftStore): DraftStore {
  const wrap = <A extends unknown[], R>(f: (...a: A) => Promise<R>) => async (...a: A): Promise<R> => {
    try { return await f(...a); } catch (e) { console.error("[cyrus-model-studio] drafts:", (e as Error).message); throw new StudioError(503, "drafts_unavailable", "Autosave is not available right now; your edits stay in
  };
  return { get: wrap(inner.get), put: wrap(inner.put), drop: wrap(inner.drop) };
}

const G = globalThis as { __cyrusMemDrafts?: DraftStore };
export function modelServiceDeps(env: Record<string, string | undefined> = process.env): ModelServiceDeps {
  // devhost / tests only: CYRUS_MODEL_DRAFTS=memory keeps drafts in the process (no table needed)
  const drafts = env.CYRUS_MODEL_DRAFTS === "memory" && env.NODE_ENV !== "production" ? (G.__cyrusMemDrafts ??= memoryDraftStore()) : safeDrafts(prismaModelDraftStore);
  return {
    ...serviceDeps(env), planOf: studioPlanOf(env), drafts,
    renderer: () => { const s = selectPreviewRenderer(env); return s.ok ? s.renderer : null; },
  };
}

export function modelApiDeps(env: Record<string, string | undefined> = process.env): ModelApiDeps {
  return {
    viewer: modelStudioViewer,
    service: modelServiceDeps(env),
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(`cyrus:${key}`, { max, windowMs }),
  };
